#pragma once
#include "mikudancestudio/pmm_scene_document.hpp"
#include <algorithm>
#include <map>
#include <set>
#include <string>

namespace mikudancestudio::format {
// Materialize a new v2 envelope after topology/path/settings changes. The old
// preservation writer remains available for byte-preserving compatibility.
// No bytes are published on failure; offsets/counts are regenerated by parsing.
bool RebuildPmmV2(const PmmSceneDocument&, PmmSceneDocument&, std::string& reason);
PmmSceneDocument NewPmmScene();

template <class T>
bool PmmTrackChains(const PmmKeyTrack<T>& track, std::vector<std::vector<T>>& chains) {
    if (track.dense.size() > 100000 || track.sparse.size() > 100000)
        return false;
    std::map<std::uint32_t, const T*> sparse;
    for (const auto& entry : track.sparse)
        if (entry.index < 0 || std::size_t(entry.index) < track.dense.size() ||
            std::size_t(entry.index) >= track.dense.size() + 100000 ||
            !sparse.emplace(std::uint32_t(entry.index), &entry.value).second)
            return false;
    std::set<std::uint32_t> visited;
    std::vector<std::vector<T>> result(track.dense.size());
    for (std::size_t root = 0; root < track.dense.size(); ++root) {
        const T* key = &track.dense[root];
        if (key->frame || key->previous)
            return false;
        auto index = std::uint32_t(root);
        result[root].push_back(*key);
        while (key->next) {
            const auto next = sparse.find(key->next);
            if (next == sparse.end() || !visited.insert(next->first).second ||
                next->second->previous != index || next->second->frame <= key->frame ||
                next->second->frame > 0x7fffffffU)
                return false;
            index = next->first;
            key = next->second;
            result[root].push_back(*key);
        }
    }
    if (visited.size() != sparse.size())
        return false;
    chains = std::move(result);
    return true;
}
template <class T>
bool BuildPmmTrack(const std::vector<std::vector<T>>& chains, PmmKeyTrack<T>& output) {
    if (chains.size() > 100000)
        return false;
    PmmKeyTrack<T> next;
    next.dense.resize(chains.size());
    next.denseRecordOffsets.resize(chains.size());
    for (std::size_t root = 0; root < chains.size(); ++root) {
        const auto& keys = chains[root];
        if (keys.empty() || keys.front().frame)
            return false;
        auto index = std::uint32_t(root);
        for (std::size_t k = 0; k < keys.size(); ++k) {
            auto value = keys[k];
            if (value.frame > 0x7fffffffU || (k && keys[k - 1].frame >= value.frame))
                return false;
            value.previous = k ? index : 0;
            const auto current = k ? std::uint32_t(next.dense.size() + next.sparse.size()) : index;
            value.next = k + 1 == keys.size()
                             ? 0
                             : std::uint32_t(next.dense.size() + next.sparse.size() + (k ? 1 : 0));
            if (!k)
                next.dense[root] = value;
            else {
                if (next.sparse.size() >= 100000)
                    return false;
                next.sparse.push_back({std::int32_t(current), 0, value});
            }
            index = current;
        }
    }
    output = std::move(next);
    return true;
}
template <class T> bool RegisterPmmKey(PmmKeyTrack<T>& track, std::size_t channel, T key) {
    std::vector<std::vector<T>> chains;
    if (!PmmTrackChains(track, chains) || channel >= chains.size())
        return false;
    auto& keys = chains[channel];
    auto found = std::lower_bound(keys.begin(), keys.end(), key.frame,
                                  [](const T& k, auto frame) { return k.frame < frame; });
    if (found != keys.end() && found->frame == key.frame)
        *found = key;
    else
        keys.insert(found, key);
    return BuildPmmTrack(chains, track);
}
template <class T>
bool DeletePmmKey(PmmKeyTrack<T>& track, std::size_t channel, std::uint32_t frame) {
    // MMD retains the frame-zero root; deleting it cannot destroy the channel.
    if (!frame)
        return false;
    std::vector<std::vector<T>> chains;
    if (!PmmTrackChains(track, chains) || channel >= chains.size())
        return false;
    auto& keys = chains[channel];
    auto found =
        std::find_if(keys.begin(), keys.end(), [frame](const T& k) { return k.frame == frame; });
    if (found == keys.end())
        return false;
    keys.erase(found);
    return BuildPmmTrack(chains, track);
}
}
